            )
        ;
    }

    public function clearAndAddMessages(): void
    {
        // clear the current schedule and add new recurring messages
        $this->schedule?->clear();
        $this->schedule?->add(
            RecurringMessage::cron('@hourly', new DoActionMessage()),
            RecurringMessage::cron('@daily', new DoAnotherActionMessage()),
        );
    }
}

